UPDATE [Доп_угли(архив)] AS Arhiv INNER JOIN Доп_угли2024 AS DopUg ON (Arhiv.YEAR = DopUg.YEAR) AND (Arhiv.NUMB1120 = DopUg.NUMB1120) SET Arhiv.NAME = DopUg.NAME, Arhiv.nazar = DopUg.nazar, Arhiv.ibor = DopUg.ibor, Arhiv.berez = DopUg.berez, Arhiv.per = DopUg.per, Arhiv.irbei = DopUg.irbei, Arhiv.kansk = DopUg.kansk, Arhiv.gusin = DopUg.gusin, Arhiv.tugn = DopUg.tugn, Arhiv.okino = DopUg.okino, Arhiv.azey = DopUg.azey, Arhiv.mug = DopUg.mug, Arhiv.cher = DopUg.cher, Arhiv.jer = DopUg.jer, Arhiv.karab = DopUg.karab, Arhiv.vork = DopUg.vork, Arhiv.intin = DopUg.intin, Arhiv.sver = DopUg.sver, Arhiv.chel = DopUg.chel, Arhiv.kizel = DopUg.kizel, Arhiv.har = DopUg.har, Arhiv.urt = DopUg.urt, Arhiv.tataur = DopUg.tataur, Arhiv.tarbag = DopUg.tarbag, Arhiv.zab_kam = DopUg.zab_kam, Arhiv.rai = DopUg.rai, Arhiv.erk = DopUg.erk, Arhiv.neru = DopUg.neru, Arhiv.pyak = DopUg.pyak, Arhiv.zyryan = DopUg.zyryan, Arhiv.gazpp = DopUg.gazpp, Arhiv.kuzngd = DopUg.kuzngd, Arhiv.kuznt = DopUg.kuznt, Arhiv.kuznss = DopUg.kuznss, Arhiv.kuznun = DopUg.kuznun, Arhiv.ekib = DopUg.ekib, Arhiv.maikub = DopUg.maikub, Arhiv.bikin = DopUg.bikin, Arhiv.razdol = DopUg.razdol, Arhiv.hankai = DopUg.hankai, Arhiv.bering = DopUg.bering, Arhiv.anad = DopUg.anad, Arhiv.gaz_prir = DopUg.gaz_prir, Arhiv.disel = DopUg.disel, Arhiv.maztop = DopUg.maztop, Arhiv.nft_proch = DopUg.nft_proch, Arhiv.domen_g = [DopUg].[domen_g], Arhiv.koks_g = [DopUg].[koks_g], Arhiv.prochgaz = DopUg.prochgaz, Arhiv.tvproch = DopUg.tvproch, Arhiv.szh_gaz = [DopUg].[szh_gaz], Arhiv.inoe = [DopUg].[inoe], Arhiv.ogodj = DopUg.ogodj, Arhiv.svo = DopUg.svo, Arhiv.karag = DopUg.karag, Arhiv.karajyra = DopUg.karajyra, Arhiv.teniz = DopUg.teniz;
